void test_a_stub_that_repaints_everything_passes_both_checks(void) {
  big_open();
  TEST_ASSERT_TRUE(ignores_the_canvas_it_starts_from(&kFull, 40));
  TEST_ASSERT_TRUE(looks_the_same_through_the_swap(&kFull, 40));
